/* From Uiverse.io by Yaya12085 - Tags: card, download */
.__UIV_SCOPE__ .card {
  max-width: 320px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-radius: 0.5rem;
  background: #606c88;
  background: -webkit-linear-gradient(to right, #3f4c6b, #606c88);
  background: linear-gradient(to right top, #3f4c6b, #606c88);
  padding: 1rem;
  color: rgb(107, 114, 128);
  box-shadow: 0px 87px 78px -39px rgba(0,0,0,0.4);
}

.__UIV_SCOPE__ .icon {
  height: 2rem;
  width: 2rem;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.5rem;
  background-color: #153586;
  color: rgb(59, 130, 246);
}

.__UIV_SCOPE__ .icon svg {
  height: 1.25rem;
  width: 1.25rem;
}

.__UIV_SCOPE__ .content {
  margin-left: 0.75rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 400;
}

.__UIV_SCOPE__ .title {
  margin-bottom: 0.25rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 600;
  color: rgb(255, 255, 255);
}

.__UIV_SCOPE__ .desc {
  margin-bottom: 0.5rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: 400;
  color: rgb(202, 200, 200);
}

.__UIV_SCOPE__ .actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-gap: 0.5rem;
  gap: 0.5rem;
}

.__UIV_SCOPE__ .download, .__UIV_SCOPE__ .notnow {
  width: 100%;
  display: inline-flex;
  justify-content: center;
  border-radius: 0.5rem;
  padding: 0.375rem 0.5rem;
  text-align: center;
  font-size: 0.75rem;
  line-height: 1rem;
  color: rgb(255, 255, 255);
  outline: 2px solid transparent;
  border: 1px solid rgba(253, 253, 253, 0.363);
}

.__UIV_SCOPE__ .download {
  background-color: #284385;
  font-weight: 600;
}

.__UIV_SCOPE__ .download:hover {
  background-color: #153586;
}

.__UIV_SCOPE__ .notnow {
  background-color: #606c88;
  font-weight: 500;
}

.__UIV_SCOPE__ .notnow:hover {
  background-color: #3f4c6b;
}

.__UIV_SCOPE__ .close {
  margin: -0.375rem -0.375rem -0.375rem auto;
  height: 2rem;
  width: 2rem;
  display: inline-flex;
  border-radius: 0.5rem;
  background-color: #606c88;
  padding: 0.375rem;
  color: rgba(255, 255, 255, 1);
  border: none;
}

.__UIV_SCOPE__ .close svg {
  height: 1.25rem;
  width: 1.25rem;
}

.__UIV_SCOPE__ .close:hover {
  background-color: rgb(58, 69, 83);
}
